-- ============================================================================
-- Veeshan's Peak 2.0 -- instanced expedition content for zone shortname 'veeshan'
--
-- Adds a version-100 instance layout (expedition template) that reuses the
-- classic Veeshan's Peak geometry and trash population, upgrades the six brood
-- + Phara Dar to Gates-of-Discord era revamp (level 70) with the VP2 "Aged"
-- loot (items 69401-69465, raidloot.com/raid/vpeak2), and places a static
-- gatekeeper NPC in the classic zone (version 0) that grants the expedition.
--
-- The classic zone (version 0) is NOT modified. Only additive inserts.
--
-- Id ranges used (free at time of writing):
--   npc_types  1500000501-1500000506 (brood 2.0), 1500000510 (gatekeeper)
--   spawngroup 60005001-60005007
--   spawn2     45000301-45000306 (brood, version 100), 45000310 (gatekeeper, v0),
--              45000001+          (mirrored trash, version 100)
--   loottable  1000001-1000006
--   lootdrop   50300001-50300006
--
-- Import:  mysql -u <user> -p peq < vp2_veeshan_peak.sql
-- ============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- ---------------------------------------------------------------------------
-- 1) Revamped brood + gatekeeper NPCs (level 70 VP2 revamp).
--    Each row is cloned from the matching classic NPC row (so appearance,
--    spells, faction and resist design are preserved) and only the scaled
--    fields are overridden. Uses a temp LIKE-copy table to avoid hand-typed
--    column lists.
-- ---------------------------------------------------------------------------
CREATE TEMPORARY TABLE vp2_npc_tmp LIKE npc_types;

-- Druushk (classic 108040 -> 1500000501)
UPDATE vp2_npc_tmp SET id=1500000501, name='Druushk', level=70, hp=520000, mana=350000,
 mindmg=500, maxdmg=1400, AC=800, hp_regen_rate=2000, mana_regen_rate=2000, loottable_id=1000001;
DELETE FROM vp2_npc_tmp;

-- Hoshkar (classic 108043 -> 1500000502)
UPDATE vp2_npc_tmp SET id=1500000502, name='Hoshkar', level=70, hp=500000, mana=350000,
 mindmg=450, maxdmg=1300, AC=780, hp_regen_rate=1900, mana_regen_rate=1900, loottable_id=1000002;
DELETE FROM vp2_npc_tmp;

-- Nexona (classic 108047 -> 1500000503)
UPDATE vp2_npc_tmp SET id=1500000503, name='Nexona', level=70, hp=560000, mana=350000,
 mindmg=520, maxdmg=1500, AC=850, hp_regen_rate=2200, mana_regen_rate=2200, loottable_id=1000003;
DELETE FROM vp2_npc_tmp;

-- Silverwing (classic 108050 -> 1500000504)
UPDATE vp2_npc_tmp SET id=1500000504, name='Silverwing', level=70, hp=480000, mana=350000,
 mindmg=420, maxdmg=1100, AC=740, hp_regen_rate=1800, mana_regen_rate=1800, loottable_id=1000004;
DELETE FROM vp2_npc_tmp;

-- Xygoz (classic 108053 -> 1500000505)
UPDATE vp2_npc_tmp SET id=1500000505, name='Xygoz', level=70, hp=550000, mana=350000,
 mindmg=520, maxdmg=1500, AC=850, hp_regen_rate=2100, mana_regen_rate=2100, loottable_id=1000005;
DELETE FROM vp2_npc_tmp;

-- Phara Dar (classic 108048 -> 1500000506)
UPDATE vp2_npc_tmp SET id=1500000506, name='Phara_Dar', level=70, hp=700000, mana=500000,
 mindmg=600, maxdmg=1800, AC=1000, hp_regen_rate=2800, mana_regen_rate=2800, loottable_id=1000006;
DELETE FROM vp2_npc_tmp;

-- Veeshan's Peak Gatekeeper (cloned from Echo_of_the_Past 1120000940 -> 1500000510)
-- non-combat: bodytype 7, no faction (0), no spells (0), no loot (0)
UPDATE vp2_npc_tmp SET id=1500000510, name='Veeshan_Peak_Gatekeeper', level=65,
 loottable_id=0, npc_faction_id=0, npc_spells_id=0, runspeed=1.25, raid_target=0, bodytype=7;

DROP TEMPORARY TABLE vp2_npc_tmp;

-- 3) VP2 loot: one lootdrop per boss with the raidloot.com/raid/vpeak2 Aged
--    drops. Items were verified present in the items table (69401-69465).
-- ---------------------------------------------------------------------------




-- ---------------------------------------------------------------------------
-- 4) Spawn groups for the revamped brood + gatekeeper
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- 5) Spawns: brood at version 100 (expedition), gatekeeper at version 0 (static)
--    Coordinates mirror the classic named locations. Long respawn so the brood
--    never repopulate mid-instance.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 6) Version-100 trash mirror of the classic zone population (generated from
--    the live spawn2 table at import time of this file's author). The classic
--    brood rows and the Echo_of_the_Past NPC are excluded here and replaced by
--    the revamped brood spawns above.
-- ---------------------------------------------------------------------------


COMMIT;


